def check_graph(edges, n):
    if not edges:
        return False
    adj = [[] for _ in range(n)]
    for u, v in edges:
        adj[u].append(v)
        adj[v].append(u)

    # Check min degree >= 1
    for i in range(n):
        if len(adj[i]) < 1:
            return False

    # Check max degree <= 2
    for i in range(n):
        if len(adj[i]) > 2:
            return False

    # Check chromatic number
    # For a graph with max degree 2, it's bipartite if it has no odd cycles.
    # A graph is bipartite if and only if it is 2-colorable.
    # Since it has at least one edge, chi >= 2.
    # So we just need to check if it's bipartite.

    color = [-1] * n
    for i in range(n):
        if color[i] == -1:
            stack = [(i, 0)]
            color[i] = 0
            while stack:
                u, c = stack.pop()
                for v in adj[u]:
                    if color[v] == -1:
                        color[v] = 1 - c
                        stack.append((v, 1 - c))
                    elif color[v] == c:
                        return False # Not bipartite
    return True

